    /** The claim's number on its sheet, given when it is opened; null for a draft. A voided claim
     *  keeps the number it had; a number is never reused. */
    public String getNumber() { return number; }
    public void setNumber(String number) { this.number = number; }
    /** The due fixed when it was settled; null while its due is live. */
    public BigDecimal getSettledDue() { return settledDue; }
    public void setSettledDue(BigDecimal settledDue) { this.settledDue = settledDue; }
    /** The user who opened it; null until it is opened. */
    public String getOpenedBy() { return openedBy; }
    public void setOpenedBy(String openedBy) { this.openedBy = openedBy; }
    /** Whether its person's last statement bound it to a figure. */
    public boolean isStated() { return stated; }
    /** The figure its person's last statement bound it to; null for n/a, or when it is not stated. */
    public BigDecimal getStatedDue() { return statedDue; }
    /**
     * The figure a statement binds it to now: its stated figure (null for n/a), but null when it
     * is not stated or is PENDING (a PENDING claim shows its live figure; a rejection binds it again).
     */
    public BigDecimal boundDue() {
        return isBound() ? statedDue : null;
    }
    /** Whether its stated figure is in force: it is stated and not PENDING. */
    public boolean isBound() {
        return stated && status != ClaimStatus.PENDING;
    }
    /** Bind it to a figure (null: n/a), or leave it unbound (live) when {@code stated} is false. */
    public void bind(boolean stated, BigDecimal statedDue) {
        this.stated = stated;
        this.statedDue = stated ? statedDue : null;
    }
    /**
     * Whether it counts toward its person's claimed and due-total, the sheet's totals and a
     * period's total: OPEN, PENDING and SETTLED do, except an OPEN or PENDING one dated within one
     * of its person's holds, or once their retirement date is reached ({@code heldOnDate}), unless
     * a statement binds it; and never one
     * deferred on {@code today}.
     */
    public boolean counts(boolean heldOnDate, LocalDate today) {
        if (isDeferredOn(today)) return false;
        return status == ClaimStatus.SETTLED || (isOpen() && (isBound() || !heldOnDate));
    }
    /**
     * Whether it counts toward a period's total as it was at the period's end, when its status then
     * was {@code statusThen} (null: it did not exist yet): as {@link #counts} with that status, its
     * statement binding and deferral as they are now.
     */
    public boolean countsAsOf(ClaimStatus statusThen, boolean heldOnDate, LocalDate today) {
        if (statusThen == null || isDeferredOn(today)) return false;
        boolean openThen = statusThen == ClaimStatus.OPEN || statusThen == ClaimStatus.PENDING;
        return statusThen == ClaimStatus.SETTLED || (openThen && (isBound() || !heldOnDate));
    }
    /** Whether it is open: OPEN, or PENDING a steward's approval. */
    public boolean isOpen() {
        return status == ClaimStatus.OPEN || status == ClaimStatus.PENDING;
    }
    /** Only a draft may be edited; to change an open claim, void it and add a new one. */
    public void checkEditable() throws InvalidClaimStatusException {
        if (status != ClaimStatus.DRAFT) throw new InvalidClaimStatusException(status);
    }

    /** A steward's approval of a PENDING claim: it is settled, its due fixed at {@code due}. */
    public void approve(BigDecimal due) throws InvalidClaimStatusException {
        if (status != ClaimStatus.PENDING) throw new InvalidClaimStatusException(status, ClaimStatus.SETTLED);
        status = ClaimStatus.SETTLED;
        settledDue = due;
    }
    /** A steward's rejection of a PENDING claim: it is OPEN again, bound again by its statement. */
    public void reject() throws InvalidClaimStatusException {
        if (status != ClaimStatus.PENDING) throw new InvalidClaimStatusException(status, ClaimStatus.OPEN);
        status = ClaimStatus.OPEN;
    }

    /** Move to the next status, when the current one allows it. */
    public void moveTo(ClaimStatus next) throws InvalidClaimStatusException {
        if (!status.canMoveTo(next)) throw new InvalidClaimStatusException(status, next);
        status = next;
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;

/**
 * A grade's rate on a sheet: a percent with two decimals, from a date (null: from the beginning of
 * time) through a date (null: with no end).
 */
public record Rate(String sheetId, String grade, BigDecimal pct, LocalDate from, LocalDate to) {

    /**
     * The grade's rate in force on the date: the one whose from-date is the latest on or before it,
     * unless its to-date is before the date. Empty when the date is before every rate the grade
     * has, or after the to-date of the rate that would apply.
     */
    public static Optional<BigDecimal> inForce(List<Rate> rates, String grade, LocalDate date) {
        return rates.stream()
                .filter((r) -> r.grade().equals(grade))
                .filter((r) -> r.from() == null || !r.from().isAfter(date))
                .max(Comparator.comparing(Rate::from, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter((r) -> r.to() == null || !r.to().isBefore(date))
                .map(Rate::pct);
    }
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The rates store: at most one rate per grade and from-date, kept per sheet. */
@Repository
public class RateRepository {

    private static final RowMapper<Rate> ROW = (rs, n) -> new Rate(rs.getString("sheet_id"),
            rs.getString("grade"), rs.getBigDecimal("pct"), rs.getObject("from_date", LocalDate.class),
            rs.getObject("to_date", LocalDate.class));

    private final JdbcTemplate jdbc;

    public RateRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's rates, by grade then from-date (none first). */
    public List<Rate> findAll(String sheetId) {
        return jdbc.query("SELECT sheet_id, grade, pct, from_date, to_date FROM rate WHERE sheet_id = ?"
                + " ORDER BY grade, from_date NULLS FIRST", ROW, sheetId);
    }

    /** Set the grade's rate from its from-date, replacing any it had for that from-date. */
    public void save(Rate rate) {
        jdbc.update("DELETE FROM rate WHERE sheet_id = ? AND grade = ? AND from_date IS NOT DISTINCT FROM ?",
                rate.sheetId(), rate.grade(), rate.from());
        jdbc.update("INSERT INTO rate (sheet_id, grade, pct, from_date, to_date) VALUES (?, ?, ?, ?, ?)",
                rate.sheetId(), rate.grade(), rate.pct(), rate.from(), rate.to());
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/** A person on a sheet, as the store holds it. {@code id} is null until first saved. */
public class Person {
    private Long id;
    private final String sheetId;
    private String name;
    private String grade;
    private Integer terms;
    private long version;
    private int statementCount;
    private String statedTotal;
    private LocalDate statementDate;
    private LocalDate retiredFrom;
    private final List<Hold> holds = new ArrayList<>();
    private final List<Long> patronIds = new ArrayList<>();
    private final TreeMap<LocalDate, String> datedGrades = new TreeMap<>();

    public Person(Long id, String sheetId, String name, String grade) {
        this(id, sheetId, name, grade, 0);
    }

    public Person(Long id, String sheetId, String name, String grade, long version) {
        this.id = id;
        this.sheetId = sheetId;
        this.name = name;
        this.grade = grade;
        this.version = version;
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getSheetId() { return sheetId; }
    public String getName() { return name; }
    public void setName(String name) { this.name = name; }
    /** The first grade they were given: in force from the beginning of time, until their first dated grade. */
    public String getGrade() { return grade; }
    public void setGrade(String grade) { this.grade = grade; }
    /** Their own terms in days, ahead of their grade's and the sheet's; null when they have none. */
    public Integer getTerms() { return terms; }
    public void setTerms(Integer terms) { this.terms = terms; }
    /** The grades recorded from a date, by from-date: each in force from it until the next. */
    public Map<LocalDate, String> getDatedGrades() { return datedGrades; }
    /** Record the grade from this date, replacing any recorded from the same date. */
    public void setGradeFrom(String grade, LocalDate from) { datedGrades.put(from, grade); }
    /** The grade in force on the date: the latest dated one on or before it, else the first grade. */
    public String gradeOn(LocalDate date) {
        Map.Entry<LocalDate, String> dated = datedGrades.floorEntry(date);
        return dated == null ? grade : dated.getValue();
    }
    /** Raised by one on each save; an edit names the version it was made from. */
    public long getVersion() { return version; }
    public void setVersion(long version) { this.version = version; }
    /** How many statements have been taken for them. */
    public int getStatementCount() { return statementCount; }
    /** The last statement's due-total (n/a when it had none); null before the first. */
    public String getStatedTotal() { return statedTotal; }
    /** The sheet's today when the last statement was taken; null before the first. */
    public LocalDate getStatementDate() { return statementDate; }
    public void setStatements(int count, String statedTotal, LocalDate statementDate) {
        this.statementCount = count;
        this.statedTotal = statedTotal;
        this.statementDate = statementDate;
    }
    /** The date they are retired from; null when not retired. Set at all, they count as retired. */
    public LocalDate getRetiredFrom() { return retiredFrom; }
    public void setRetiredFrom(LocalDate retiredFrom) { this.retiredFrom = retiredFrom; }
    public boolean isRetired() { return retiredFrom != null; }
    /** Their holds, in the order added: each from a date to an optional to-date. */
    public List<Hold> getHolds() { return holds; }
    /** Whether they have any hold at all. */
    public boolean isHeld() { return !holds.isEmpty(); }
    /** Whether the date is within one of their holds: an OPEN claim on it, not bound by a statement, counts in no total. */
    public boolean heldOn(LocalDate date) { return holds.stream().anyMatch((h) -> h.covers(date)); }
    /** Whether their retirement date is reached on {@code today}: retired from it or an earlier date. */
    public boolean retiredOn(LocalDate today) { return retiredFrom != null && today != null && !today.isBefore(retiredFrom); }
    /**
     * Whether an OPEN or PENDING claim of theirs on the date, not bound by a statement, counts in no
     * total on {@code today}: the date is within one of their holds, or their retirement date is reached.
     */
    public boolean heldOn(LocalDate date, LocalDate today) { return heldOn(date) || retiredOn(today); }
    /** The ids of the people they name as patrons, in the order named. */
    public List<Long> getPatronIds() { return patronIds; }
    /** Whether a claim on this date is refused: they are retired from an earlier date. */
    public boolean retiredBefore(LocalDate date) { return retiredFrom != null && date.isAfter(retiredFrom); }
}
