package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;

/**
 * A sheet's settings. The figure settings are dated ({@code dated}, by key, each value from a
 * from-date; a blank value is "none"): its clerk limit, the highest due a clerk may settle (none: no
 * limit), its floor, the least a claim's live due may be, and its terms, the days after a claim's
 * date that it is due by, and its late percent, what an overdue claim's due gains per full 30 days
 * overdue, and its terms per grade (a grade with none uses the sheet's terms), and its cap (none:
 * no cap), the most a person's due-total may be, and its proof threshold (none: none), above which a
 * claim's due, on the claim's date, needs a proof before it is settled or approved. The value in force on a date is the one with the
 * latest from-date on or before it; before every from-date the starting value (floor 1.00, late
 * percent 0.00, terms 14; none for the others). A claim takes its floor, late percent and terms on
 * its date; the clerk limit and the cap are those in force on the sheet's today ({@code today}).
 * Not dated: its policy date (null: the sheet's today): a claim dated before it rounds half up, one
 * on or after it half to even, and its period numbering from (null: off): while the sheet's today
 * is on or after it, a claim opened is numbered within its period, and its permission matrix
 * ({@code perms}, by action, the roles that may take it as a comma separated list; blank or missing:
 * the standing rule, open, settle, void and close by clerk and steward, reassign and reopen by steward),
 * and its grace days (null: off): when the sheet's today is changed, every open period whose to-date
 * plus the grace days is before the new today is closed.
 */
public record Settings(String sheetId, LocalDate today, Map<String, NavigableMap<LocalDate, String>> dated,
        LocalDate policyDate, LocalDate periodNumberingFrom, Map<String, String> perms, Integer graceDays) {
    /** The grades that may have their own terms. */
    public static final List<String> GRADES = List.of("A", "B", "C");

    public static final String CLERK_LIMIT = "clerk-limit";
    public static final String FLOOR = "floor";
    public static final String TERMS = "terms";
    public static final String LATE_PCT = "late-pct";
    public static final String CAP = "cap";
    public static final String PROOF_THRESHOLD = "proof-threshold";

    /** The actions of the permission matrix, in the order they are shown and audited. */
    public static final List<String> ACTIONS = List.of("open", "settle", "void", "reassign", "close", "reopen");

    /** The key of an action's entry in the permission matrix. */
    public static String permKey(String action) {
        return "perm-" + action;
    }

    /** The roles that may take an action by the standing rule. */
    public static List<String> standingRoles(String action) {
        return "reassign".equals(action) || "reopen".equals(action) ? List.of("steward") : List.of("clerk", "steward");
    }

    /** The roles that may take an action: its entry in the permission matrix, else the standing rule. */
    public List<String> rolesFor(String action) {
        String entry = perms == null ? null : perms.get(action);
        if (entry == null || entry.isBlank()) return standingRoles(action);
        return java.util.Arrays.stream(entry.split(",")).map(String::trim).filter((r) -> !r.isEmpty()).toList();
    }

    /** Whether a role may take an action. */
    public boolean allows(String action, String role) {
        if (net.officefloor.hq.app.role.Role.VIEWER.equals(role)) return false; // a viewer changes nothing
        return rolesFor(action).contains(role);
    }

    /** The key of a grade's own terms. */
    public static String gradeTermsKey(String grade) {
        return "terms-" + grade;
    }

    /** A sheet's floor until it is set. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    /** A sheet's terms until they are set. */
    public static final int DEFAULT_TERMS = 14;

    /** A sheet's late percent until it is set. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    /** The value of a key in force on a date: null when none is recorded on or before it, '' for none. */
    public String valueOn(String key, LocalDate date) {
        NavigableMap<LocalDate, String> values = dated.get(key);
        if (values == null || date == null) return null;
        Map.Entry<LocalDate, String> entry = values.floorEntry(date);
        return entry == null ? null : entry.getValue();
    }

    private BigDecimal figureOn(String key, LocalDate date) {
        String value = valueOn(key, date);
        return value == null || value.isEmpty() ? null : new BigDecimal(value).setScale(2);
    }

    /** The floor in force on a date. */
    public BigDecimal floorOn(LocalDate date) {
        BigDecimal floor = figureOn(FLOOR, date);
        return floor != null ? floor : DEFAULT_FLOOR;
    }

    /** The late percent in force on a date. */
    public BigDecimal latePctOn(LocalDate date) {
        BigDecimal pct = figureOn(LATE_PCT, date);
        return pct != null ? pct : DEFAULT_LATE_PCT;
    }

    /** The sheet's terms in force on a date. */
    public int termsOn(LocalDate date) {
        String value = valueOn(TERMS, date);
        return value == null || value.isEmpty() ? DEFAULT_TERMS : Integer.parseInt(value);
    }

    /** A grade's own terms in force on a date, or null when it takes the sheet's. */
    public Integer gradeTermsOn(String grade, LocalDate date) {
        String value = valueOn(gradeTermsKey(grade), date);
        return value == null || value.isEmpty() ? null : Integer.valueOf(value);
    }

    /** The terms of a person's claim on a date: their own, else their grade's then, else the sheet's. */
    public int termsFor(net.officefloor.hq.app.person.Person person, LocalDate date) {
        Integer own = person.getTerms();
        return own != null ? own : termsFor(person.gradeOn(date), date);
    }

    /** The terms of a grade on a date: its own, else the sheet's. */
    public int termsFor(String grade, LocalDate date) {
        Integer own = gradeTermsOn(grade, date);
        return own != null ? own : termsOn(date);
    }

    /** The clerk limit in force on a date (null: no limit). */
    public BigDecimal clerkLimitOn(LocalDate date) {
        return figureOn(CLERK_LIMIT, date);
    }

    /** The proof threshold in force on a date (null: none). */
    public BigDecimal proofThresholdOn(LocalDate date) {
        return figureOn(PROOF_THRESHOLD, date);
    }

    /**
     * Whether a claim dated {@code date} with a due (null: n/a) and a proofs count needs a proof
     * before it is settled or approved: its due is above the proof threshold in force on its date
     * and it has no proofs. A due of n/a, or no threshold, needs none.
     */
    public boolean needsProof(BigDecimal due, LocalDate date, int proofs) {
        BigDecimal threshold = proofThresholdOn(date);
        return proofs == 0 && threshold != null && due != null && due.compareTo(threshold) > 0;
    }

    /** The cap in force on a date (null: none). */
    public BigDecimal capOn(LocalDate date) {
        return figureOn(CAP, date);
    }

    /**
     * How every figure of a claim that rounds by {@code date} is rounded: half up before the policy
     * date ({@code today} when it is blank), half to even on or after it.
     */
    public RoundingMode rounding(LocalDate date, LocalDate today) {
        LocalDate policy = policyDate != null ? policyDate : today;
        return date.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** Whether a period ending {@code to} is past its grace days on {@code today}: never while they are off. */
    public boolean pastGrace(LocalDate to, LocalDate today) {
        return graceDays != null && to.plusDays(graceDays).isBefore(today);
    }

    /** Whether a claim opened on {@code today} is numbered within its period. */
    public boolean numbersByPeriod(LocalDate today) {
        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
    }

    /** A person's due-total (null: n/a) held to the cap in force on {@code today}. A due-total of n/a is not capped. */
    public BigDecimal capped(BigDecimal dueTotal, LocalDate today) {
        BigDecimal cap = capOn(today);
        return cap == null || dueTotal == null || dueTotal.compareTo(cap) <= 0 ? dueTotal : cap;
    }

    /** Whether a due (null: n/a) is within the clerk limit in force on {@code today}. A due of n/a is within any limit. */
    public boolean withinClerkLimit(BigDecimal due, LocalDate today) {
        BigDecimal clerkLimit = clerkLimitOn(today);
        return clerkLimit == null || due == null || due.compareTo(clerkLimit) <= 0;
    }
}
package net.officefloor.hq.app.person;

import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.Statement;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The people store, kept per sheet. */
@Repository
public class PersonRepository {

    private static final String COLUMNS = "id, sheet_id, name, grade, terms, version, statement_count, stated_total, statement_date, retired_from";

    private static final RowMapper<Person> ROW = (rs, n) -> {
        Person person = new Person(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name"),
                rs.getString("grade"), rs.getLong("version"));
        person.setTerms(rs.getObject("terms", Integer.class));
        person.setStatements(rs.getInt("statement_count"), rs.getString("stated_total"),
                rs.getObject("statement_date", LocalDate.class));
        person.setRetiredFrom(rs.getObject("retired_from", LocalDate.class));
        return person;
    };

    private final JdbcTemplate jdbc;

    public PersonRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's people, in the order they were added. */
    public List<Person> findAll(String sheetId) {
        List<Person> people = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? ORDER BY id",
                ROW, sheetId);
        Map<Long, Person> byId = new HashMap<>();
        people.forEach((p) -> byId.put(p.getId(), p));
        jdbc.query("SELECT person_id, from_date, grade FROM person_grade WHERE sheet_id = ?",
                (rs) -> {
                    Person person = byId.get(rs.getLong("person_id"));
                    if (person != null) person.setGradeFrom(rs.getString("grade"), rs.getObject("from_date", LocalDate.class));
                }, sheetId);
        jdbc.query("SELECT person_id, patron_id FROM person_patron WHERE sheet_id = ? ORDER BY person_id, patron_id",
                (rs) -> {
                    Person person = byId.get(rs.getLong("person_id"));
                    if (person != null) person.getPatronIds().add(rs.getLong("patron_id"));
                }, sheetId);
        jdbc.query("SELECT person_id, from_date, to_date FROM person_hold WHERE sheet_id = ? ORDER BY id",
                (rs) -> {
                    Person person = byId.get(rs.getLong("person_id"));
                    if (person != null) person.getHolds().add(hold(rs));
                }, sheetId);
        return people;
    }

    /** The person with this id on the sheet, or null when there is none. */
    public Person find(String sheetId, long id) {
        List<Person> found = jdbc.query(
                "SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND id = ?",
                ROW, sheetId, id);
        if (found.isEmpty()) return null;
        Person person = found.get(0);
        loadGrades(person);
        loadHolds(person);
        person.getPatronIds().addAll(jdbc.queryForList(
                "SELECT patron_id FROM person_patron WHERE sheet_id = ? AND person_id = ? ORDER BY patron_id",
                Long.class, sheetId, id));
        return person;
    }

    /** Record {@code patron} as one of the person's patrons. */
    public void addPatron(Person person, Person patron) {
        jdbc.update("INSERT INTO person_patron (sheet_id, person_id, patron_id) VALUES (?, ?, ?)",
                person.getSheetId(), person.getId(), patron.getId());
        person.getPatronIds().add(patron.getId());
    }

    /** The person on the sheet with this name, ignoring case and surrounding spaces, or null when there is none. */
    public Person findByName(String sheetId, String name) {
        List<Person> found = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ?"
                + " AND LOWER(TRIM(name)) = LOWER(TRIM(?)) ORDER BY id", ROW, sheetId, name);
        if (found.isEmpty()) return null;
        loadGrades(found.get(0));
        loadHolds(found.get(0));
        return found.get(0);
    }

    private void loadGrades(Person person) {
        jdbc.query("SELECT from_date, grade FROM person_grade WHERE sheet_id = ? AND person_id = ?",
                (rs) -> {
                    person.setGradeFrom(rs.getString("grade"), rs.getObject("from_date", LocalDate.class));
                }, person.getSheetId(), person.getId());
    }

    private void loadHolds(Person person) {
        jdbc.query("SELECT from_date, to_date FROM person_hold WHERE sheet_id = ? AND person_id = ? ORDER BY id",
                (rs) -> {
                    person.getHolds().add(hold(rs));
                }, person.getSheetId(), person.getId());
    }

    private static Hold hold(java.sql.ResultSet rs) throws java.sql.SQLException {
        return new Hold(rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class));
    }

    /** Record the person's dated grades as they hold them now, replacing those stored. */
    private void saveGrades(Person person) {
        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ?",
                person.getSheetId(), person.getId());
        person.getDatedGrades().forEach((from, grade) -> jdbc.update(
                "INSERT INTO person_grade (sheet_id, person_id, from_date, grade) VALUES (?, ?, ?, ?)",
                person.getSheetId(), person.getId(), Date.valueOf(from), grade));
    }

    /** Whether a person other than {@code exceptId} has this name on the sheet, ignoring case. */
    public boolean nameTaken(String sheetId, String name, Long exceptId) {
        Integer count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND LOWER(TRIM(name)) = LOWER(TRIM(?))"
                        + " AND id <> ?",
                Integer.class, sheetId, name, exceptId == null ? -1L : exceptId);
        return count != null && count > 0;
    }

    /**
     * Record the person's statements (their count, last due-total and date), leaving the rest as stored.
     * The last statement is kept as the one numbered by the count; any numbered after it are dropped.
     */
    public void saveStatements(Person person) {
        Date date = person.getStatementDate() == null ? null : Date.valueOf(person.getStatementDate());
        jdbc.update("UPDATE person SET statement_count = ?, stated_total = ?, statement_date = ? WHERE id = ? AND sheet_id = ?",
                person.getStatementCount(), person.getStatedTotal(), date,
                person.getId(), person.getSheetId());
        jdbc.update("DELETE FROM person_statement WHERE sheet_id = ? AND person_id = ? AND seq >= ?",
                person.getSheetId(), person.getId(), person.getStatementCount());
        if (person.getStatementCount() > 0) {
            jdbc.update("INSERT INTO person_statement (sheet_id, person_id, seq, stated_total, statement_date) VALUES (?, ?, ?, ?, ?)",
                    person.getSheetId(), person.getId(), person.getStatementCount(), person.getStatedTotal(), date);
        }
    }

    /**
     * The person's statement numbered {@code seq} (from 1): its due-total and date, or null when it
     * was not kept (taken before statements were kept), or there is none.
     */
    public StatedFigure findStatement(Person person, int seq) {
        List<StatedFigure> found = jdbc.query(
                "SELECT stated_total, statement_date FROM person_statement WHERE sheet_id = ? AND person_id = ? AND seq = ?",
                (rs, n) -> new StatedFigure(rs.getString("stated_total"), rs.getObject("statement_date", LocalDate.class)),
                person.getSheetId(), person.getId(), seq);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Record the date the person is retired from, leaving the rest as stored. */
    public void saveRetired(Person person) {
        jdbc.update("UPDATE person SET retired_from = ? WHERE id = ? AND sheet_id = ?",
                person.getRetiredFrom() == null ? null : Date.valueOf(person.getRetiredFrom()),
                person.getId(), person.getSheetId());
    }

    /** Record a new hold on the person, leaving the rest as stored. */
    public void addHold(Person person, Hold hold) {
        jdbc.update("INSERT INTO person_hold (sheet_id, person_id, from_date, to_date) VALUES (?, ?, ?, ?)",
                person.getSheetId(), person.getId(), Date.valueOf(hold.from()),
                hold.to() == null ? null : Date.valueOf(hold.to()));
    }

    /**
     * Insert a new person (assigning its id) or update an existing one, raising its version. False
     * when the stored person is no longer at the version it was loaded at: nothing is written.
     */
    public boolean save(Person person) {
        if (person.getId() != null) {
            int updated = jdbc.update("UPDATE person SET name = ?, grade = ?, terms = ?, version = version + 1"
                    + " WHERE id = ? AND sheet_id = ? AND version = ?",
                    person.getName(), person.getGrade(), person.getTerms(), person.getId(), person.getSheetId(),
                    person.getVersion());
            if (updated == 0) return false;
            person.setVersion(person.getVersion() + 1);
            saveGrades(person);
            return true;
        }
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO person (sheet_id, name, grade, terms) VALUES (?, ?, ?, ?)",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, person.getSheetId());
            ps.setString(2, person.getName());
            ps.setString(3, person.getGrade());
            ps.setObject(4, person.getTerms(), java.sql.Types.INTEGER);
            return ps;
        }, keys);
        person.setId(keys.getKey().longValue());
        saveGrades(person);
        return true;
    }
}
package net.officefloor.hq.app.claim;

import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.Statement;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The claims store, kept per sheet. */
@Repository
public class ClaimRepository {

    private static final String COLUMNS = "id, sheet_id, person_id, amount, claim_date, note, status, claim_number, settled_due, opened_by, stated, stated_due, corrects, due_by, deferred_until, proofs, split_from, late_entry,"
            + " (SELECT c.claim_date FROM claim c WHERE c.sheet_id = claim.sheet_id AND c.person_id = claim.person_id"
            + " AND c.claim_number = claim.corrects) AS corrected_date,"
            + " CASE WHEN locked_on = (SELECT s.today FROM sheet s WHERE s.id = claim.sheet_id) THEN locked_by END AS locked_by_now";

    private static final RowMapper<Claim> ROW = (rs, n) -> {
        Claim claim = new Claim(rs.getLong("id"),
            rs.getString("sheet_id"), rs.getLong("person_id"), rs.getBigDecimal("amount"),
            rs.getDate("claim_date").toLocalDate(), rs.getString("note"),
            ClaimStatus.valueOf(rs.getString("status")),
            rs.getString("claim_number"), rs.getBigDecimal("settled_due"),
            rs.getString("opened_by"));
        claim.bind(rs.getBoolean("stated"), rs.getBigDecimal("stated_due"));
        claim.setCorrects(rs.getString("corrects"));
        claim.setDueBy(rs.getDate("due_by").toLocalDate());
        java.sql.Date deferred = rs.getDate("deferred_until");
        claim.setDeferredUntil(deferred == null ? null : deferred.toLocalDate());
        claim.setProofs(rs.getInt("proofs"));
        claim.setSplitFrom(rs.getString("split_from"));
        claim.setLateEntry(rs.getBoolean("late_entry"));
        claim.setLockedBy(rs.getString("locked_by_now"));
        java.sql.Date corrected = rs.getDate("corrected_date");
        claim.setCorrectedDate(corrected == null ? null : corrected.toLocalDate());
        return claim;
    };

    private final JdbcTemplate jdbc;

    public ClaimRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's claims, newest first (a moved claim listed as made when it was moved). */
    public List<Claim> findAll(String sheetId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? ORDER BY listed DESC, id DESC",
                ROW, sheetId);
    }

    /** The person's claims on the sheet, newest first. */
    public List<Claim> findByPerson(String sheetId, long personId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY listed DESC, id DESC",
                ROW, sheetId, personId);
    }

    /** The claim with this id on the sheet, or null when there is none. */
    public Claim find(String sheetId, long id) {
        List<Claim> found = jdbc.query(
                "SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND id = ?", ROW, sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /**
     * Mark the claim OPEN in the store when it is still DRAFT there, holding its row until the
     * request commits so two opens of the same claim cannot both go through; false when another
     * request changed it first.
     */
    public boolean markOpened(Claim claim) {
        return jdbc.update("UPDATE claim SET status = 'OPEN' WHERE id = ? AND sheet_id = ? AND status = 'DRAFT'",
                claim.getId(), claim.getSheetId()) == 1;
    }

    /**
     * Lock the claim for {@code user}'s editor on {@code today}, in one statement so two users
     * opening it at once cannot both hold it; false when another user holds it on that today (a
     * lock taken on an earlier today has lapsed).
     */
    public boolean lock(Claim claim, String user, LocalDate today) {
        return jdbc.update("UPDATE claim SET locked_by = ?, locked_on = ? WHERE id = ? AND sheet_id = ?"
                + " AND (locked_by IS NULL OR locked_by = ? OR locked_on IS NULL OR locked_on <> ?)",
                user, Date.valueOf(today), claim.getId(), claim.getSheetId(), user, Date.valueOf(today)) == 1;
    }

    /** Release the locks {@code user} holds on the same person's other claims. */
    public void unlockOthers(Claim claim, String user) {
        jdbc.update("UPDATE claim SET locked_by = NULL, locked_on = NULL WHERE sheet_id = ? AND person_id = ?"
                + " AND locked_by = ? AND id <> ?", claim.getSheetId(), claim.getPersonId(), user, claim.getId());
    }

    /** Release the claim's lock: only when {@code user} holds it, or whoever does when null. */
    public void unlock(Claim claim, String user) {
        if (user == null) {
            jdbc.update("UPDATE claim SET locked_by = NULL, locked_on = NULL WHERE id = ? AND sheet_id = ?",
                    claim.getId(), claim.getSheetId());
        } else {
            jdbc.update("UPDATE claim SET locked_by = NULL, locked_on = NULL WHERE id = ? AND sheet_id = ? AND locked_by = ?",
                    claim.getId(), claim.getSheetId(), user);
        }
    }

    /** Whether a user other than {@code user} holds the claim's lock on {@code today}. */
    public boolean lockedByOther(Claim claim, String user, LocalDate today) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE id = ? AND sheet_id = ?"
                + " AND locked_by IS NOT NULL AND locked_by <> ? AND locked_on = ?",
                Integer.class, claim.getId(), claim.getSheetId(), user, Date.valueOf(today));
        return n != null && n > 0;
    }

    /**
     * The sheet's next claim number, taken in one statement so two claims opened at the same
     * moment never share a number; it is never given out again.
     */
    public int nextNumber(String sheetId) {
        return jdbc.queryForObject("SELECT last_claim_number FROM FINAL TABLE"
                + " (UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = ?)",
                Integer.class, sheetId);
    }

    /**
     * The next number in one period's sequence on the sheet ({@code sequence} '' for claims in no
     * period), counting from 1; taken in one statement so two claims opened at the same moment
     * never share a number, and never given out again.
     */
    public int nextNumberIn(String sheetId, String sequence) {
        jdbc.update("MERGE INTO period_number p USING (VALUES (CAST(? AS VARCHAR(200)), CAST(? AS VARCHAR(200)))) v (sheet_id, seq_name)"
                + " ON p.sheet_id = v.sheet_id AND p.seq_name = v.seq_name"
                + " WHEN NOT MATCHED THEN INSERT (sheet_id, seq_name, last_number) VALUES (v.sheet_id, v.seq_name, 0)",
                sheetId, sequence);
        return jdbc.queryForObject("SELECT last_number FROM FINAL TABLE"
                + " (UPDATE period_number SET last_number = last_number + 1 WHERE sheet_id = ? AND seq_name = ?)",
                Integer.class, sheetId, sequence);
    }

    /** The sheet's next place in its claims list, taken in one statement; never given out again. */
    private long nextListed(String sheetId) {
        return jdbc.queryForObject("SELECT last_claim_listed FROM FINAL TABLE"
                + " (UPDATE sheet SET last_claim_listed = last_claim_listed + 1 WHERE id = ?)",
                Long.class, sheetId);
    }

    /** Insert a new claim (assigning its id) or update an existing one. */
    public void save(Claim claim) {
        if (claim.getId() != null) {
            if (claim.isRelisted()) {
                jdbc.update("UPDATE claim SET person_id = ?, listed = ? WHERE id = ? AND sheet_id = ?",
                        claim.getPersonId(), nextListed(claim.getSheetId()), claim.getId(), claim.getSheetId());
            }
            jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, claim_number = ?, settled_due = ?, opened_by = ?, stated = ?, stated_due = ?, corrects = ?, deferred_until = ?, proofs = ? WHERE id = ? AND sheet_id = ?",
                    claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(),
                    claim.getStatus().name(), claim.getNumber(), claim.getSettledDue(), claim.getOpenedBy(),
                    claim.isStated(), claim.getStatedDue(), claim.getCorrects(),
                    claim.getDeferredUntil() == null ? null : Date.valueOf(claim.getDeferredUntil()), claim.getProofs(), claim.getId(),
                    claim.getSheetId());
            return;
        }
        long listed = nextListed(claim.getSheetId());
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status, corrects, listed, due_by, split_from, claim_number, opened_by, late_entry) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, claim.getSheetId());
            ps.setLong(2, claim.getPersonId());
            ps.setBigDecimal(3, claim.getAmount());
            ps.setDate(4, Date.valueOf(claim.getDate()));
            ps.setString(5, claim.getNote());
            ps.setString(6, claim.getStatus().name());
            ps.setString(7, claim.getCorrects());
            ps.setLong(8, listed);
            ps.setDate(9, Date.valueOf(claim.getDueBy()));
            ps.setString(10, claim.getSplitFrom());
            ps.setString(11, claim.getNumber());
            ps.setString(12, claim.getOpenedBy());
            ps.setBoolean(13, claim.isLateEntry());
            return ps;
        }, keys);
        claim.setId(keys.getKey().longValue());
    }
}
