content.content:
== V1__sheet.sql
-- A sheet: everything else in the app is kept per sheet, keyed by its id. A sheet is created the
-- first time its id is loaded, empty.
CREATE TABLE sheet (
    id VARCHAR(200) PRIMARY KEY
);
== V2__sheet_today.sql
-- A sheet's "today": the date every date-dependent decision and every default date on the sheet
-- uses, instead of the real clock. It starts as the real date when the sheet is created.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CURRENT_DATE WHERE today IS NULL;
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
== V3__person.sql
-- The people on a sheet, listed in the order they were added (by id). A grade is one of A, B, C.
CREATE TABLE person (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet(id),
    name VARCHAR(200) NOT NULL,
    grade CHAR(1) NOT NULL
);
CREATE INDEX person_sheet ON person(sheet_id, id);
== V4__person_name_trimmed.sql
-- A person's name is stored without surrounding spaces, and is unique on its sheet ignoring case
-- (checked by the app before saving).
UPDATE person SET name = TRIM(name);
== V5__claim.sql
-- A person's claims, listed newest first (by id). An amount is 0.00 or more, with up to two
-- decimals; a date defaults to the sheet's today when the claim is made; a note may be empty.
CREATE TABLE claim (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet(id),
    person_id BIGINT NOT NULL REFERENCES person(id),
    amount DECIMAL(19, 2) NOT NULL,
    claim_date DATE NOT NULL,
    note VARCHAR(1000) NOT NULL DEFAULT ''
);
CREATE INDEX claim_sheet ON claim(sheet_id, id);
== V6__rate.sql
-- A sheet's rate for each grade: a percent with two decimals. A grade with no row has no rate.
CREATE TABLE rate (
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet(id),
    grade CHAR(1) NOT NULL,
    pct DECIMAL(19, 2) NOT NULL,
    PRIMARY KEY (sheet_id, grade)
);
== V7__claim_status.sql
-- A claim's status: DRAFT when made, then OPEN, then SETTLED; a DRAFT or OPEN claim may be VOID.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) NOT NULL DEFAULT 'DRAFT';
== V8__claim_number.sql
-- A claim's number: given when it is opened, the next on its sheet (1, 2, ...), with no gaps and
-- never reused. A draft has none; voiding a claim clears it. The sheet keeps the last number given.
ALTER TABLE sheet ADD COLUMN last_claim_number INT NOT NULL DEFAULT 0;
ALTER TABLE claim ADD COLUMN claim_number INT;
== V9__claim_settled_due.sql
-- A settled claim's due, fixed when it was settled: its amount times its person's grade's rate at
-- that moment. Null for a claim not settled, or settled while its grade had no rate (its due stays
-- live, as an open claim's does).
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(19, 2);
== V10__rate_from.sql
-- A rate may carry a from-date: it applies to claims dated on or after it, until a later from-date
-- for the same grade. A null from-date applies from the beginning of time. At most one rate per
-- sheet, grade and from-date (null counted as one value), kept by RateRepository.save.
ALTER TABLE rate DROP PRIMARY KEY;
ALTER TABLE rate ADD COLUMN from_date DATE;
CREATE INDEX rate_sheet_grade ON rate (sheet_id, grade);
== V11__claim_opened_by.sql
-- The signed-in user who opened a claim; null until it is opened. That user may not settle it.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(100);
== V12__person_version.sql
-- The version of a person, raised by one on each save, so an edit made from an older version
-- (someone else saved the person in the meantime) can be refused.
ALTER TABLE person ADD COLUMN version BIGINT NOT NULL DEFAULT 0;
== V13__statement.sql
-- A person's statements: how many have been taken, and the last one's due-total (n/a when it had
-- none) and date (the sheet's today when it was taken). Null total and date until the first.
ALTER TABLE person ADD COLUMN statement_count INT NOT NULL DEFAULT 0;
ALTER TABLE person ADD COLUMN stated_total VARCHAR(30);
ALTER TABLE person ADD COLUMN statement_date DATE;
-- A claim bound by its person's last statement: stated, with the figure it had then (null: n/a).
-- Its person's next statement rebinds it, or leaves it unbound (live) when it does not count then.
ALTER TABLE claim ADD COLUMN stated BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(19, 2);
== V14__period.sql
-- A sheet's periods: a name unique on the sheet, and a from and to date, inclusive. No two of a
-- sheet's periods overlap (checked when one is added).
CREATE TABLE period (
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet(id),
    name VARCHAR(200) NOT NULL,
    from_date DATE NOT NULL,
    to_date DATE NOT NULL,
    PRIMARY KEY (sheet_id, name)
);
== V15__period_closed.sql
-- A period can be closed. Closing fixes its due-total at that moment (later rate changes do not
-- alter it), and no claim dated inside a closed period can be added, edited, opened, settled or voided.
ALTER TABLE period ADD COLUMN closed BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(19, 2);
== V16__person_retired.sql
-- A person retired from a date (null: not retired). A person with a date set counts as retired at
-- once, whatever the date; no claim dated after it can be added to them.
ALTER TABLE person ADD COLUMN retired_from DATE;
== V17__person_held.sql
-- Whether a person is on hold: while held, their OPEN claims count in no total.
ALTER TABLE person ADD COLUMN held BOOLEAN NOT NULL DEFAULT FALSE;
== V18__role_setting.sql
-- A user's role on a sheet: clerk or steward. A name with no row is a clerk.
CREATE TABLE sheet_role (
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet(id),
    user_name VARCHAR(200) NOT NULL,
    role VARCHAR(20) NOT NULL,
    PRIMARY KEY (sheet_id, user_name)
);
-- A sheet's clerk limit: the highest due a clerk may settle, with two decimals. Null: no limit.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(19, 2);
== V19__floor_setting.sql
-- A sheet's floor: the least a claim's live due may be, with two decimals.
ALTER TABLE sheet ADD COLUMN due_floor DECIMAL(19, 2) DEFAULT 1.00 NOT NULL;
== V20__terms_setting.sql
-- A sheet's terms: the number of days after a claim's date that it is due by.
ALTER TABLE sheet ADD COLUMN terms INT DEFAULT 14 NOT NULL;
== V21__late_pct_setting.sql
-- A sheet's late percent: what an overdue claim's due gains, per full 30 days overdue, with two decimals.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(19, 2) DEFAULT 0.00 NOT NULL;
== V22__person_patron.sql
-- The people a person names as their patrons: other people on the same sheet, each at most once.
CREATE TABLE person_patron (
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet(id),
    person_id BIGINT NOT NULL REFERENCES person(id),
    patron_id BIGINT NOT NULL REFERENCES person(id),
    PRIMARY KEY (person_id, patron_id)
);
CREATE INDEX person_patron_sheet ON person_patron(sheet_id);
== V23__person_grade.sql
-- A person's grade is dated: person.grade is the first grade they were given, in force from the
-- beginning of time; each row here is a grade in force from its date, until a later one. At most
-- one row per person and from-date, kept by PersonRepository.save.
CREATE TABLE person_grade (
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet(id),
    person_id BIGINT NOT NULL REFERENCES person(id),
    from_date DATE NOT NULL,
    grade CHAR(1) NOT NULL,
    PRIMARY KEY (person_id, from_date)
);
CREATE INDEX person_grade_sheet ON person_grade(sheet_id, person_id);
== V24__claim_corrects.sql
-- A claim with a negative amount is a correction: it names, by number, the SETTLED claim of the
-- same person that it corrects. Null for any other claim.
ALTER TABLE claim ADD COLUMN corrects INT;
== V25__policy_date_setting.sql
-- A sheet's policy date: a claim dated before it rounds half up, one on or after it half to even.
-- Null: the sheet's today.
ALTER TABLE sheet ADD COLUMN policy_date DATE;
== V26__period_numbering.sql
-- A sheet's period numbering from: while it is a date and the sheet's today is on or after it, a
-- claim opened is numbered within its period (<period name>-<n>), or X-<n> when it is in no period.
-- Null: off, claims take the sheet-wide number.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
-- A claim's number, and the number a correction names, are now text: a sheet-wide number (1, 2, ...)
-- or a number within a period (P1-1, X-1, ...).
ALTER TABLE claim ALTER COLUMN claim_number VARCHAR(200);
ALTER TABLE claim ALTER COLUMN corrects VARCHAR(200);
-- The last number given in each period's sequence on a sheet ('' is the sequence of claims in no
-- period). Never given out again.
CREATE TABLE period_number (
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet(id),
    seq_name VARCHAR(200) NOT NULL,
    last_number INT NOT NULL,
    PRIMARY KEY (sheet_id, seq_name)
);
== V27__claim_listed.sql
-- Where a claim is listed: claims are listed newest first by this, not by id, so a claim moved to
-- another person is listed as that person's newest. A claim takes the sheet's next place when it is
-- made and again when it is moved; the sheet keeps the last place given.
ALTER TABLE sheet ADD COLUMN last_claim_listed BIGINT NOT NULL DEFAULT 0;
ALTER TABLE claim ADD COLUMN listed BIGINT NOT NULL DEFAULT 0;
UPDATE claim SET listed = id;
UPDATE sheet SET last_claim_listed = COALESCE((SELECT MAX(c.id) FROM claim c WHERE c.sheet_id = sheet.id), 0);
== V28__grade_terms.sql
-- A sheet's terms per grade: the days after a claim's date that a claim of that grade is due by.
-- A grade with no row uses the sheet's terms.
CREATE TABLE grade_terms (
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet(id),
    grade CHAR(1) NOT NULL,
    terms INT NOT NULL,
    PRIMARY KEY (sheet_id, grade)
);
-- A claim's due-by, fixed when it is made: its date plus the terms of its person's grade in force on
-- its date. It does not move when the terms or the claim's date change later.
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim SET due_by = DATEADD('DAY', (SELECT s.terms FROM sheet s WHERE s.id = claim.sheet_id), claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
== V29__claim_log.sql
-- A claim's status log: one line per status it has had, oldest first (by id), each with the user
-- who made the change, the sheet's today then and the claim's due as computed at that moment
-- ('n/a' when it had none). A claim's first line is its DRAFT, written when it was added.
CREATE TABLE claim_log (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet(id),
    claim_id BIGINT NOT NULL REFERENCES claim(id),
    status VARCHAR(10) NOT NULL,
    by_user VARCHAR(200) NOT NULL,
    on_date DATE NOT NULL,
    due VARCHAR(30) NOT NULL
);
CREATE INDEX claim_log_sheet ON claim_log(sheet_id, claim_id, id);
== V30__person_hold.sql
-- A person's holds: each from a date until an optional to-date (null: open-ended), both inclusive.
-- A person may have several over time. While a claim's date is within one of its person's holds,
-- an OPEN claim not bound by a statement counts in no total. Replaces person.held: a person held
-- before is given one open-ended hold from the beginning of time.
CREATE TABLE person_hold (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet(id),
    person_id BIGINT NOT NULL REFERENCES person(id),
    from_date DATE NOT NULL,
    to_date DATE
);
CREATE INDEX person_hold_sheet ON person_hold(sheet_id, person_id, id);
INSERT INTO person_hold (sheet_id, person_id, from_date, to_date)
    SELECT sheet_id, id, DATE '0001-01-01', NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
== V31__rate_to.sql
-- A rate may carry a to-date: it applies through it, and a claim dated after it with no later
-- from-date for the grade has no rate. A null to-date applies with no end.
